const recordAttemptUsage = `-- name: RecordAttemptUsage :exec
UPDATE attempts a SET
    cpu_seconds = GREATEST(a.cpu_seconds, ($1::double precision[])[array_position($2::text[], a.id)]),
    peak_memory = GREATEST(a.peak_memory, ($3::bigint[])[array_position($2::text[], a.id)]),
    runner_cpu_seconds = GREATEST(a.runner_cpu_seconds, ($4::double precision[])[array_position($2::text[], a.id)]),
    runner_memory = GREATEST(a.runner_memory, ($5::bigint[])[array_position($2::text[], a.id)]),
    seconds = GREATEST(a.seconds, ($6::double precision[])[array_position($2::text[], a.id)]),
    rows = GREATEST(a.rows, ($7::bigint[])[array_position($2::text[], a.id)]),
    bytes = GREATEST(a.bytes, ($8::bigint[])[array_position($2::text[], a.id)])
WHERE a.org_id = $9 AND a.id = ANY($2::text[])
`

type RecordAttemptUsageParams struct {
	CpuSeconds       []float64
	Ids              []string
	PeakMemory       []int64
	RunnerCpuSeconds []float64
	RunnerMemory     []int64
	Seconds          []float64
	Rows             []int64
	Bytes            []int64
	OrgID            uuid.UUID
}

// What runners' reports say of what they run. Reports may arrive out of order
// across a result, so usage only grows.
func (q *Queries) RecordAttemptUsage(ctx context.Context, arg RecordAttemptUsageParams) error {
	_, err := q.db.Exec(ctx, recordAttemptUsage,
		arg.CpuSeconds,
		arg.Ids,
		arg.PeakMemory,
		arg.RunnerCpuSeconds,
		arg.RunnerMemory,
		arg.Seconds,
		arg.Rows,
		arg.Bytes,
		arg.OrgID,
	)
	return err
}

const replaceRunning = `-- name: ReplaceRunning :execrows
UPDATE dispatches SET state = 'pending', runner = NULL, start_deadline = NULL, run_deadline = NULL, lease_deadline = NULL
WHERE org_id = $1 AND data_plane_id = $2 AND id = $3 AND runner = $4 AND state = 'running' AND light = ''
`

type ReplaceRunningParams struct {
	OrgID       uuid.UUID
	DataPlaneID string
	ID          string
	Runner      *string
}

// A runner with no room for what was placed on it: it's placed again.
func (q *Queries) ReplaceRunning(ctx context.Context, arg ReplaceRunningParams) (int64, error) {
	result, err := q.db.Exec(ctx, replaceRunning,
		arg.OrgID,
		arg.DataPlaneID,
		arg.ID,
		arg.Runner,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const returnPlaced = `-- name: ReturnPlaced :exec
UPDATE dispatches SET state = 'pending', runner = NULL, start_deadline = NULL
WHERE org_id = $1 AND data_plane_id = $2 AND runner = $3 AND state = 'placed'
`

type ReturnPlacedParams struct {
	OrgID       uuid.UUID
	DataPlaneID string
	Runner      *string
}

// A draining runner won't start what's placed on it, so it's placed again.
func (q *Queries) ReturnPlaced(ctx context.Context, arg ReturnPlacedParams) error {
	_, err := q.db.Exec(ctx, returnPlaced, arg.OrgID, arg.DataPlaneID, arg.Runner)
	return err
}

const returnUnstarted = `-- name: ReturnUnstarted :execrows
UPDATE dispatches SET state = 'pending', runner = NULL, start_deadline = NULL
WHERE org_id = $1 AND state = 'placed' AND start_deadline <= now()
`

// Attempts whose runner didn't start them in time go back to wait for room,
// keeping their place in the queue.
func (q *Queries) ReturnUnstarted(ctx context.Context, orgID uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, returnUnstarted, orgID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const runnerDisconnected = `-- name: RunnerDisconnected :exec
UPDATE runners SET report_time = LEAST(report_time, now() - ($1::bigint * interval '1 millisecond'))
WHERE org_id = $2 AND data_plane_id = $3 AND id = $4
`

type RunnerDisconnectedParams struct {
	LapseMs     int64
	OrgID       uuid.UUID
	DataPlaneID string
	ID          string
}

// A runner whose long poll was dropped has probably died, so it stops counting
// for placement until it reports again.
func (q *Queries) RunnerDisconnected(ctx context.Context, arg RunnerDisconnectedParams) error {
	_, err := q.db.Exec(ctx, runnerDisconnected,
		arg.LapseMs,
		arg.OrgID,
		arg.DataPlaneID,
		arg.ID,
	)
	return err
}

