const syncAttempts = `-- name: SyncAttempts :many
SELECT org_id, id, pipeline_id, sync_id, attempt, size_cpu, size_memory, size_reason, cpu_seconds, peak_memory, runner_cpu_seconds, runner_memory, seconds, rows, bytes, code, create_time FROM attempts
WHERE org_id = $1 AND sync_id = ANY($2::uuid[])
ORDER BY sync_id, attempt, create_time
`

type SyncAttemptsParams struct {
	OrgID   uuid.UUID
	SyncIds []uuid.UUID
}

// The syncs' attempts, in order.
func (q *Queries) SyncAttempts(ctx context.Context, arg SyncAttemptsParams) ([]Attempt, error) {
	rows, err := q.db.Query(ctx, syncAttempts, arg.OrgID, arg.SyncIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Attempt
	for rows.Next() {
		var i Attempt
		if err := rows.Scan(
			&i.OrgID,
			&i.ID,
			&i.PipelineID,
			&i.SyncID,
			&i.Attempt,
			&i.SizeCpu,
			&i.SizeMemory,
			&i.SizeReason,
			&i.CpuSeconds,
			&i.PeakMemory,
			&i.RunnerCpuSeconds,
			&i.RunnerMemory,
			&i.Seconds,
			&i.Rows,
			&i.Bytes,
			&i.Code,
			&i.CreateTime,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const takeManualSync = `-- name: TakeManualSync :one
WITH marked AS (
    SELECT p.id, p.manual_sync_time FROM pipelines p
    WHERE p.org_id = $1 AND p.id = $2 AND p.manual_sync_time IS NOT NULL
    FOR UPDATE
)
UPDATE pipelines u SET manual_sync_time = NULL
FROM marked
WHERE u.org_id = $1 AND u.id = marked.id
RETURNING marked.manual_sync_time > now() - interval '5 minutes' AS manual
`

type TakeManualSyncParams struct {
	OrgID uuid.UUID
	ID    uuid.UUID
}

// Whether the API just started this pipeline's sync by hand. RETURNING sees
// the row as updated, so the mark is read first.
func (q *Queries) TakeManualSync(ctx context.Context, arg TakeManualSyncParams) (bool, error) {
	row := q.db.QueryRow(ctx, takeManualSync, arg.OrgID, arg.ID)
	var manual bool
	err := row.Scan(&manual)
	return manual, err
}

const unfinishedWorkOfSyncs = `-- name: UnfinishedWorkOfSyncs :many
SELECT id FROM dispatches
WHERE org_id = $1 AND state <> 'finished' AND input->>'SyncID' = ANY($2::text[])
`

type UnfinishedWorkOfSyncsParams struct {
	OrgID   uuid.UUID
	SyncIds []string
}

// What the syncs have running or waiting, their post-sync steps included.
func (q *Queries) UnfinishedWorkOfSyncs(ctx context.Context, arg UnfinishedWorkOfSyncsParams) ([]string, error) {
	rows, err := q.db.Query(ctx, unfinishedWorkOfSyncs, arg.OrgID, arg.SyncIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

